"""Auditor-style replay: every possible rolling window must hold <= limit allowed calls,
and retry_after must be exactly sufficient."""
import random, sys, importlib, math
sys.path.insert(0, "/tmp"); sys.path.insert(0, ".")
from ratelimit.limiter import RateLimiter as New
from audit_old import RateLimiter as Old

def worst_window(times, window):
    # max number of allowed calls in any half-open window (t-window, t]
    times=sorted(times); best=0; j=0
    for i,t in enumerate(times):
        while times[j] <= t-window: j+=1
        best=max(best, i-j+1)
    return best

def replay(cls, limit, window, seed, n=3000):
    rng=random.Random(seed); rl=cls(limit, window); now=0.0; allowed=[]
    for _ in range(n):
        now += rng.choice([0.0, rng.random()*0.3, rng.random()*window*1.5])
        if rl.allow("k", now): allowed.append(now)
    return worst_window(allowed, window)

